"""Normal API binding for the existing UUID/UTC creation capabilities.

Included by normal compiler dispatch only. Providers are test/host dependencies,
not persisted semantic values or new CLI inputs. Default providers stay unchanged.
"""
from contextvars import ContextVar
from uuid import UUID

_creation_providers = ContextVar("lykoi_creation_providers", default={})
_resource_value_of = value_of
_resource_execute = execute


def value_of(assignment, inputs):
    if assignment["source"] != "capability" or assignment["id"] not in _creation_providers.get():
        return _resource_value_of(assignment, inputs)
    value = _creation_providers.get()[assignment["id"]]()
    kind = by_id("capabilities", assignment["id"])["kind"]
    if kind == "utc_clock":
        valid = isinstance(value, str) and utc_timestamp(value)
    elif kind == "uuid_v4":
        try:
            valid = isinstance(value, str) and UUID(value).version == 4
        except (ValueError, AttributeError):
            valid = False
    else:
        valid = False
    if not valid:
        raise Failure("invalid_state")
    return value


def execute(behavior, inputs, clock=None, *, providers=None):
    providers = {} if providers is None else providers
    allowed = {a["id"] for a in behavior["assignments"] if a["source"] == "capability"} if behavior["kind"] == "create" else set()
    if (type(providers) is not dict or not set(providers) <= allowed
            or not set(providers) <= set(behavior["requires"])
            or not all(callable(p) for p in providers.values())):
        raise ValueError("Providers must bind declared creation capabilities only")
    token = _creation_providers.set(providers)
    try:
        return _resource_execute(behavior, inputs, clock)
    finally:
        _creation_providers.reset(token)



"""Self-contained pure predicate interpreter inserted by normal lowering."""
from datetime import datetime


def predicate_value(o, record, inputs, stages, resources):
    k = o["kind"]
    if k == "literal":
        return o["value"]
    if k == "value":
        return stages[o["stage"]]
    return (record if k == "field" else inputs if k == "parameter" else resources).get(o["name"])


def predicate_eval(tree, record=None, inputs=None, stages=None, resources=None):
    record, inputs, stages, resources = record or {}, inputs or {}, stages or {}, resources or {}
    k = tree["kind"]
    def ev(t):
        return predicate_eval(t, record, inputs, stages, resources)
    if k in ("and", "or"):
        values = [ev(c) for c in tree["children"]]  # all pure operands, no effects
        return all(values) if k == "and" else any(values)
    if k == "not":
        return not ev(tree["child"])
    if k == "present":
        o = tree["operand"]
        return o["stage"] in stages if o["kind"] == "value" else o["name"] in inputs
    def value(o):
        return predicate_value(o, record, inputs, stages, resources)
    if k == "is_null":
        return value(tree["operand"]) is None
    left, right = value(tree["left"]), value(tree["right"])
    if left is None or right is None:
        return False
    def normalized(v):
        if tree["left"]["type"]["type"] == "timestamp":
            return datetime.fromisoformat(v.replace("Z", "+00:00"))
        if tree["policy"]["normalization"] == "strip":
            v = v.strip()
        return v.casefold() if tree["policy"]["case"] == "casefold" else v
    left = normalized(left)
    if k == "member":
        return any(left == normalized(v) for v in right)
    right = normalized(right)
    op = tree["operator"]
    if op == "eq":
        return left == right
    if op == "lt":
        return left < right
    if op == "le":
        return left <= right
    if op == "gt":
        return left > right
    return left >= right

